// Firefly 🐛 #WCCChallenge
//
// I don't have much time to code this week...
// So, here is just a simple particle system! (hehe)
//
// This work is inspired by "GPU-Accelerated Particles with WebGL 2":
// https://gpfault.net/posts/webgl2-particles.txt.html
//
// The article is the best WebGL2-based particle system tutorial I've found so far; highly recommended!
// Of course, I'm also very open to any more article suggestions!
// Sharing is beautiful; thank you!

/* [Inlined Multi-Tab] shader.js */
/* [Inlined Multi-Tab] shader.js */
import Olon from "https://cdn.jsdelivr.net/npm/olon@0.2.4/dist/Olon.min.js"
/* [Inlined Multi-Tab] tools.js */

const COLS = 80
const ROWS = 80
const MAX_AMOUNT = COLS * ROWS
const MIN_AGE = 0
const MAX_AGE = 30
const SPEED = 0.5
let BORN_AMOUNT = 0

const ol = Olon(innerWidth, innerHeight, true)

ol.blend({ sfactor: ol.SRC_ALPHA, dfactor: ol.ONE })
ol.enableBlend()

const TFV = ["vPosition", "vAge", "vLife", "vVel"]
const updateProgram = ol.createProgram(UPDATE_VERT, UPDATE_FRAG, TFV)
const renderProgram = ol.createProgram(RENDER_VERT, RENDER_FRAG)

const aPosition = { name: "aPosition", unit: "f32", size: 2 }
const aAge = { name: "aAge", unit: "f32", size: 1 }
const aLife = { name: "aLife", unit: "f32", size: 1 }
const aVel = { name: "aVel", unit: "f32", size: 2 }
const aCoord = { name: "aCoord", unit: "f32", size: 2 }
const aTexCoord = { name: "aTexCoord", unit: "f32", size: 2 }

const updateAttribs = [aPosition, aAge, aLife, aVel]
const renderAttribs = [aPosition, aAge, aLife]
const quadAttribs = [aCoord, aTexCoord]

const particleData = []
for (var i = 0; i < MAX_AMOUNT; i++) {
	const LIFE = random(MIN_AGE, MAX_AGE)
	// prettier-ignore
	///////////////// aPosition  aAge       aLife  aVel
	particleData.push(0, 0,      LIFE + 1,  LIFE,  0, 0)
}
const initData = ol.Data(particleData)
const quadData = ol.quadData()

const buffer0 = ol.createBuffer(initData, ol.STREAM_DRAW)
const buffer1 = ol.createBuffer(initData, ol.STREAM_DRAW)
const quadBuffer = ol.createBuffer(quadData, ol.STATIC_DRAW)

// prettier-ignore
const VAOConfig = (buffer, stride, attributes, divisor) => ({ buffer, stride, attributes, divisor })
const updateVAO0 = ol.createVAO(updateProgram, [
	VAOConfig(buffer0, 4 * 6, updateAttribs),
])
const updateVAO1 = ol.createVAO(updateProgram, [
	VAOConfig(buffer1, 4 * 6, updateAttribs),
])
const renderVAO0 = ol.createVAO(renderProgram, [
	VAOConfig(buffer0, 4 * 6, renderAttribs, 1),
	VAOConfig(quadBuffer, 4 * 4, quadAttribs),
])
const renderVAO1 = ol.createVAO(renderProgram, [
	VAOConfig(buffer1, 4 * 6, renderAttribs, 1),
	VAOConfig(quadBuffer, 4 * 4, quadAttribs),
])

const buffers = [buffer0, buffer1]
const updateVAOs = [updateVAO0, updateVAO1]
const renderVAOs = [renderVAO0, renderVAO1]
let [read, write] = [0, 1]

ol.render(() => {
	BORN_AMOUNT = min(MAX_AMOUNT, BORN_AMOUNT + 10)

	ol.clearColor(0, 0, 0, 1)
	ol.clearDepth()

	ol.use({
		program: updateProgram,
	}).run(() => {
		ol.transformFeedback(updateVAOs[read], buffers[write], ol.POINTS, () => {
			ol.uniform("uMouse", ol.mouse)
			ol.uniform("uSpeed", SPEED)
			ol.uniform("uTime", ol.frame / 60)
			ol.uniform("uScale", ol.width / ol.height)
			ol.points(0, BORN_AMOUNT)
		})
	})

	ol.use({
		VAO: renderVAOs[read],
		program: renderProgram,
	}).run(() => {
		ol.uniform("uScale", ol.width / ol.height)
		ol.trianglesInstanced(0, 6, BORN_AMOUNT)
	})

	// swap
	;[read, write] = [write, read]
})



// === Tab: shader.js ===

import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.1.3/src/Shox.js"

const PI = 3.141592653589793
const TAU = 6.283185307179586

const UPDATE_VERT = `
	precision mediump float;

	uniform vec2 uMouse;
	uniform float uSpeed;
	uniform float uTime;

	in vec2 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aVel;

	out vec2 vPosition;
	out float vAge;
	out float vLife;
	out vec2 vVel;

	uniform float uScale;

	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.snoise3DImage}
	${Shox.hash}
	${Shox.displace}

	vec4 noise(vec2 uv, float scal, float gain, float ofst, float expo, vec3 move) {
		vec4 noise;
		noise  =     1.*snoise3DImage((uv-vec2(421., 132))*1., scal, gain, ofst, expo, move);
		noise +=     .5*snoise3DImage((uv-vec2(913., 687))*2., scal, gain, ofst, expo, move);
		noise +=    .25*snoise3DImage((uv-vec2(834., 724))*4., scal, gain, ofst, expo, move);
		noise +=   .125*snoise3DImage((uv-vec2(125., 209))*8., scal, gain, ofst, expo, move);
		noise +=  .0625*snoise3DImage((uv-vec2(387., 99))*16., scal, gain, ofst, expo, move);
		noise /= 1.9375;
		return noise;
	}

	void main() {
		float scal = 5.;
		float gain = 2.;
		float ofst = .5;
		float expo = 2.;
		vec3  move = vec3(0., 0., uTime*.25);
		vec4 dimg = noise(aPosition/vec2(1., uScale), scal, gain, ofst, expo, move);

		vec2 noise = dimg.rg;

		vec2 force = 3.*(2.*noise.rg-1.);

		if (aAge >= aLife) {
			vPosition = vec2(gl_VertexID%80, gl_VertexID/80)/vec2(80.-1.);
			vPosition = 2.*vPosition-1.;
			vPosition = 2.*hash22(vPosition*314159.26)-1.;

			vPosition = uMouse;
			vAge = 0.;
			vLife = aLife;
			vVel = .95*aVel+uSpeed*force*.016*.5;
		} else {
			vPosition = aPosition+aVel*.016;
			vAge = aAge+.016;
			vLife = aLife;
			vVel = .95*aVel+uSpeed*force*.016*.5;
		}
	}
`

const UPDATE_FRAG = `
	precision mediump float;
	void main() { discard; }
`

const RENDER_VERT = `
	precision mediump float;

	in vec2 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aCoord;
	in vec2 aTexCoord;

	out float vAge;
	out float vLife;
	out vec2 vTexCoord;

	uniform float uScale;

	void main() {
		float t = aAge/aLife;
		vAge = aAge;
		vLife = aLife;
		vTexCoord = aTexCoord;

		float tc = .5+.5*cos(2.*${PI}*t-${PI});
		float ti = 1.-t;
		gl_Position = vec4(aPosition+ti*.05*aCoord*vec2(1., uScale), 0., 1.);
	}
`

const RENDER_FRAG = `
	precision mediump float;

	uniform sampler2D uSprite;

	in float vAge;
	in float vLife;
	in vec2 vTexCoord;

	out vec4 fragColor;

	float circle(vec2 uv, vec2 pos, float r, float blur) {
		return smoothstep(blur, -blur, length(uv-pos)-r);
	}

	void main() {
		vec2 uv = vTexCoord;
		float t =  vAge/vLife;
		float tc = .5+.5*cos(${TAU}*t-${PI});
		float ti = 1.-t;

		float cir = circle(uv, vec2(.5), .1, .1);
		vec4 color;
		color.rgb = vec3(1., .8, .3);
		// color.a = tc;
		color.a = ti;

		fragColor = color * cir;
	}
`



// === Tab: tools.js ===

const random = (min = 0, max = 1) => {
	return Math.random() * (max - min) + min
}

const floor = (value) => {
	return Math.floor(value)
}

const min = (value1, value2) => {
	return Math.min(value1, value2)
}

const pow = (x, y) => {
	return Math.pow(x, y)
}

